from collections import defaultdict

def parse_cnf(clauses):
    variable_counts = defaultdict(int)
    cnf = []
    for clause in clauses:
        num_lits, literals = clause.split(" ")[0], clause.split(" ")[1].replace(" ","")
        num_lits = int(num_lits)
        clauses_per_lit = 0
        variable = []
        for i in range(1, num_lits + 1):
            curr = int(literals[i * -1 * clauses_per_lit + i - 1])
            variable.append(curr)
            variable_counts[curr] += 1
            clauses_per_lit += 1
        cnf.append(set(variable))
    return cnf, variable_counts

def simplify_cnf(cnf):
    new_cnf = []
    while True:
        flag = False
        for clause in cnf:
            size_of_clause = len(clause)
            if size_of_clause == 1:
                flag = True
                continue
            for negation in clause:
                other_literals = list(clause)
                del other_literals[other_literals.index(negation)]
                if len(other_literals) == 1:
                    flag = True
                    continue
                new_clause = clause.copy()
                new_clause.remove(negation)
                for other_lit in other_literals:
                    if flag and (other_lit not in clause or other_lit in new_clause):
                        flag = False
                        break
                if flag:
                    flag = True
                    break
                new_cnf.append(new_clause)
                break
        if not flag:
            break
    return new_cnf

def find_clauses_with_majority(cnf):
    majority = 0
    clauses_with_majority = []
    for clause in cnf:
        if len(clause) > majority + 1:
            major = 1
        else:
            major = -1
        if major == 1:
            while clause and major > 0:
                clauses_with_majority.append(clause.pop())
        if major == -1:
            while clause and major < 0:
                clauses_with_majority.append(clause.pop())
    return clauses_with_majority

def find_satisfying_assignment(clauses, variable_counts):
    for clause in clauses:
        for i in range(len(clause)):
            lit = clause[i] if variable_counts[clause[i]] % 2 == 1 else -clause[i]
            if variable_counts[abs(lit)] > variable_counts[abs(clause[0])]:
                clause[i] = 1
            else:
                clause[i] = -1
                break
    return clause

