# Function to check if two numbers are coprime
def is_coprime(a, b):
    return gcd(a, b) == 1

mod = 10**9 + 7

def count_plans(n, cities, roads):
    graph = defaultdict(list)
    city_to_level = {i: i for i in range(1, n + 1)}
    for p, dest in enumerate(roads):
        graph[p].append(dest)

    visited = [False] * n
    for i in range(1, n + 1):
        if not visited[i - 1] and is_coprime(i, cities[i - 1]):
            city_to_level[i] = city_to_level[i - 1]
            continue
        for j in graph[i - 1]:
            dist = next(iter(graph[j])).distance_from(i, mod)
            if dist is None or visited[i - 1] + 1 + cities[i - 1] <= cities[dist] + 1 + visited[dist]:
                city_to_level[i] = dist
        visited[i - 1] = True
    level_count = defaultdict(int)
    for city in range(1, n + 1):
        level_count[city_to_level[city]] += 1

    # Function to calculate the number of ways to split '1' into two parts in n cases with at least one part being '0' and coprime
    # with num
    def count_polynomials(n, num, poly):
        polys = 0
        for div in range(1, n // 2 + 1):
            if gcd(div, num) == 1: 
                polys += 1 if n % div == 0 else 0
        poly[n] = len(poly[n - 1]) if polys > 0 else 0
        for j in range(n - 1, -1, -1):
            poly[j] = poly[j + 1][:-len(poly[max(0, j + 1):j])] if poly[j + 1][:-len(poly[max(0, j + 1):j])] \
                and gcd(j + 1, num) == 1 else poly[j + 1]
        poly[0] = mod * (2 - polys) % mod
        return poly

    result = 1
    for levels in range(1, n + 1):
        for level_in, level_out in level_count.items():
            result = result * count_polynomials(max(1, levels - 1), gcd(levels, cities[level_in] + 1), [level_in] * level_in + [level_out] * level_out ) % mod
        result = result * power(2, gcd(levels, cities[level_count[1]]) - 1, mod) % mod
    return result

def power(base, exp, mod):
    result = 1
    while exp > 0:
        if exp % 2 > 0:
            result = (result * base) % mod
        exp //= 2
        base = (base * base) % mod
    return result

