    points.sort()  # Sort points based on x-coordinate, if equal then by y-coordinate
    hull = []

    # Get upper and lower hull
    for point in points:
        while len(hull) > 1 and check(hull[-2], hull[-1], point, m):
            hull.pop()
        hull.append(point)

    # Reverse the hull and check for odd number of points, return half the hull
    hull.reverse()
    alh, blh = [None]*(-n % 2 + 1), [None]*(-n % 2 + 1)

    for i in range(n // 2):
        alh[n-i] = blh[i] = hull[i * 2]

    return sum((abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])) * lcm(abs(p1[0] - p3[0]), abs(p1[1] - p3[1])) for (i, (p1, p2, p3)) in zip((list(alh), alh), (list(alh), blh), list(blh[-1:] + blh)))

def check(a, b, point, m):
    if abs(a[0] - b[0]) == 0:
        return abs((a[1] - m) - b[1]) <= abs(point[1] - m)
    if abs(a[1] - b[1]) == 0:
        return abs((a[0] - m) - b[0]) <= abs(point[0] - m)
    flag1 = (0 > a[0] - m) ^ (0 > b[0] - m) ^ (point[0] - m > 0)
    flag2 = (0 > a[1] - m) ^ (0 > b[1] - m) ^ (point[1] - m > 0)
    #print(flag1, 'and', flag2)
    return flag1 * flag2 > 0

def gcd(x, y):
    while y:
        x, y = y, x % y
    return x

def lcm(x, y):
    return x * y // gcd(x, y)

if __name__ == "__main__":
    points, m = map(int, input().split())
    points = [list(map(int, input().split())) for _ in range(points)]
    print("%.10f" % convex_hull(points, m))

