# Chebyshev2: 2D Chebyshev distance. R1 at 0, R2 at infinity.
@lru_cache(maxsize=None)
def chebyshev(A, R1, R2):
    if R1 == 0:
        return -sum(A[:R2+1])
    if R2 == float('inf'):
        return sum(A[int(R1/i)] for i in range(1, len(A)))
    return 2**(max(0, min(R1+1, R2+2))) * chebyshev(A, R1-1, R2-1)

