from functools import lru_cache

def permutation_count(N, modulo):
    @lru_cache(maxsize=None)
    def compute_permutations(start, end):
        if start + 1 > end:
            return 1
        return pow(2, end - start - 1, modulo) * compute_permutations(start + 1, end)

    mod = 1000000007
    result = 0
    for l in range(N):
        for r in range(1, N):
            end_permutation = r if l == 0 else l
            total_permutations = compute_permutations(0, r - 1)
            valid_orders = (total_permutations - compute_permutations(0, l - 1) - compute_permutations(l + 1, end_permutation) + mod) % mod
            result = (result + valid_orders) % mod
    return result

