    clausifiable = set()
    cnf_without_negated_originals = [sorted(cnf[i]) for i in range(len(cnf))]
    for literal in cnf_without_negated_originals:
        if not set(literal).isdisjoint(clausifiable):
            cnf_without_negated_originals = [sorted(cnf[i]) for i in range(len(cnf)) if sorted(cnf[i])[-1] not in set(literal)]
        for place, negation in enumerate(literal):
            if negation:
                clausifiable.add((negation,))
            else:
                if (-1) * negation in clausifiable:
                    clausifiable.add((-1) * negation)
                else:
                    clausifiable.add((literal[place],))
