def is_satisfiable(clauses: List[List[int]]) -> str:
    visited = [0] * len(clauses)  # Indicates which literals are visited
    variables = [-1] * len(clauses)  # Maps each literal to its corresponding variable index
    assignments = []  # Store the assignment of variables

    def dfs(index: int):
        if index == len(clauses):
            return True
        literal = clauses[index][0]
        if literal >= 0 and not visited[literal]:
            visited[literal] = 1
            assign = (assignments[-clauses[index][0] - 1] if index % 2 else not assignments[-clauses[index][0] - 1])
            for j in range(1, len(clauses[index])):
                if variables[abs(clauses[index][j] - 1)] < 0:
                    variables[abs(clauses[index][j] - 1)] = len(assignments)
                    if assignments[len(assignments) - 1] and assign is True:  # Potential conflict
                        return False
                    if not assign is True:
                        if not dfs(index + 1):
                            return False
                    assignments[-clauses[index][j] - 1] = assign
            return True
        return False

    for i in range(len(clauses)):
        if not dfs(i):
            return "NO"
        assignments.append(True)
        for j in range(len(clauses[i])):
            if variables[abs(clauses[i][j] - 1)] == -1 or abs(variables[abs(clauses[i][j] - 1)]) == -clauses[i][j]:
                variables[abs(clauses[i][j])] = -clauses[i][j]
                assignments[-2] = variables[-clauses[i][j] + len(assignments)]
    return "YES" + " " + " ".join(map(str, assignments))

