def solve():
    for total_cost in range(1, c + 1):
        if total_cost in to_unite:
            to_unite.remove(total_cost)
            total_cost -= total_cost

        for coin in to_unite:
            total_cost -= coin

        cap = 0
        while cap < c:
            val = heappop(to_unite)
            if cap + val > c:
                continue

            if cap + val == c:
                cap += val
                heappush(to_unite, val)
                break

            if val + min(*map(lambda x: x - cap, to_unite)) > c:
                continue

            elif val + min(*map(lambda x: x - cap, to_unite)) == c:
                cap += val
                heappush(to_unite, val)
                break

            elif val + min(*map(lambda x: x - cap, to_unite)) > cap + min(*map(lambda x: x - cap, to_unite)):
                heappush(to_unite, val)
                cap += val

            elif val + min(*map(lambda x: x - cap, to_unite)) == cap + min(*map(lambda x: x - cap, to_unite)):
                heappush(to_unite, val - c)  # Removing common proceeding coin
                cap += val
                break

            else:
                heappush(to_unite, val - cap)  # Removing common proceeding coin
                cap += val

        else:
            return total_cost

    return min_cost

