from collections import defaultdict

def dfs(node, parent, depth, distance, connect):
    best_distance = depth + dist[node]
    best_connect = []

    for child, weight in connect[node]:
        if child != parent:
            best_connect.append(child)
            best_connect.sort()
            best_distance = max(best_distance, dfs(child, node, depth + weight, distance, connect) + dist[node])

    if best_distance < distance:
        distance = best_distance
        best_connect = best_connect[:1]  # Only save the most optimal
        best_connect.sort()
    return distance, best_connect

def add_connect(node):
    if children[node] is not None:
        for child in children[node]:
            children[child].append(node)
        return bestlink.connect(node, children[node])

def preprocess_connect(tree, n):
    for i in range(n - 1):
        parent, child, weight = tree[i][1:]
        connect = defaultdict(list)
        children[parent] = None
        children[child] = connect
    for i in range(n - 1):
        parent, child, weight = tree[i][1:]
        connect = children[parent]
        connect.append(child)
    add_connect(0, None)
    return bestlink.depth(0, None), bestlink.dist()

def solve(tree):
